begin read only;
with e as(select * from public._m029_recovery_expected),p as(select e.*,exists(select 1 from public.clients where id=e.client_id and workspace_id=e.workspace_id) client_ok,exists(select 1 from public.opportunities where id=e.application_id and workspace_id=e.workspace_id and created_by=e.owner_user_id) application_ok,exists(select 1 from public.campaigns where id=e.goal_id and workspace_id=e.workspace_id) goal_ok,exists(select 1 from public.tasks where id=e.work_id and workspace_id=e.workspace_id and status='cancelled') work_ok,exists(select 1 from public.personal_operational_records where id=e.content_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id) content_ok,exists(select 1 from public.business_memory_records where id=e.knowledge_id and workspace_id=e.workspace_id) knowledge_ok,exists(select 1 from public.operational_objects where id=e.quick_capture_id and workspace_id=e.workspace_id and owner_user_id=e.owner_user_id) capture_ok,exists(select 1 from public.personal_operational_records where id=e.converted_content_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id) converted_ok from e)
select jsonb_build_object('result',case when to_regclass('public.canonical_domain_drafts') is null and to_regprocedure('public.prepare_internal_action(text,text,uuid,text,text,text,text,jsonb)') is not null and to_regprocedure('public.save_canonical_domain_object(text,uuid,bigint,jsonb,text)') is null and client_ok and application_ok and goal_ok and work_ok and content_ok and knowledge_ok and capture_ok and converted_ok then 'M029_RECOVERY_M028_BASELINE_PASS' else 'FAIL' end,'accepted_objects_retained',(client_ok::int+application_ok::int+goal_ok::int+work_ok::int+content_ok::int+knowledge_ok::int+capture_ok::int+converted_ok::int),'external_execution','LOCKED','paid_ai_jpy',0) verification from p;
rollback;
